/**
 * Catálogo canônico normalizado de aeroportos.
 */
const deduplicatedList: AirportRecord[] = [];
const deduplicatedMap = new Map<string, AirportRecord>();

for (const t of RAW_AIRPORTS_DATA) {
  const iata = t[0].trim().toUpperCase();
  if (deduplicatedMap.has(iata)) continue;

  const record: AirportRecord = {
    iata_code: iata,
    icao_code: t[1].trim().toUpperCase(),
    name: t[2].trim(),
    city: t[3].trim(),
    state_province: t[4].trim() || undefined,
    country: t[5].trim(),
    country_code: t[6].trim().toUpperCase(),
    latitude: t[7],
    longitude: t[8],
    timezone: t[9].trim(),
    is_commercial: true,
  };

  deduplicatedList.push(record);
  deduplicatedMap.set(iata, record);
}

// Suporte a alias histórico para garantir retrocompatibilidade total com a baseline (ex: CAL -> Caldas Novas CLV)
if (!deduplicatedMap.has("CAL") && deduplicatedMap.has("CLV")) {
  const clv = deduplicatedMap.get("CLV")!;
  const calAlias: AirportRecord = {
    ...clv,
    iata_code: "CAL",
  };
  deduplicatedList.push(calAlias);
  deduplicatedMap.set("CAL", calAlias);
}

export const GLOBAL_AIRPORTS_CATALOG: readonly AirportRecord[] = deduplicatedList;

export const AIRPORTS_BY_IATA_MAP: ReadonlyMap<string, AirportRecord> = deduplicatedMap;

/**
 * Remove acentos e normaliza para busca rápida.
 */
export function normalizeAirportSearchText(value: string): string {
  return value
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

/**
 * Busca O(1) de aeroporto pelo código IATA (3 letras).
 */
export function getAirportByIata(iataCode?: string | null): AirportRecord | undefined {
  if (!iataCode) return undefined;
  const clean = iataCode.trim().toUpperCase();
  return AIRPORTS_BY_IATA_MAP.get(clean);
}

/**
 * Formata rótulo amigável para exibição em seletores e cards.
 * Exemplo: "XAP — Chapecó/SC (Aeroporto Serafin Enoss Bertaso)" ou "LIS — Lisboa, Portugal (Aeroporto Humberto Delgado)"
 */
export function formatAirportLabel(airport: AirportRecord): string {
  const location =
    airport.state_province && airport.country_code === "BR"
      ? `${airport.city}/${airport.state_province}`
      : `${airport.city}, ${airport.country}`;
  return `${airport.iata_code} — ${location} (${airport.name})`;
}

export interface SearchAirportsOptions {
  country?: string;
  limit?: number;
}

/**
 * Motor de busca textual em tempo real no catálogo global de aeroportos.
 * Pontuação ponderada:
 * - Match exato IATA: 1000 pts
 * - Match exato ICAO: 950 pts
 * - Prefixo IATA: 800 pts
 * - Match exato cidade: 750 pts
 * - Prefixo cidade: 650 pts
 * - Cidade contém termo: 500 pts
 * - Nome do aeroporto contém termo: 400 pts
 * - Estado ou país contém termo: 200 pts
 * - Aeroportos do Brasil recebem bônus de prioridade (+10 pts)
 */
export function searchAirportsCatalog(query: string, limit?: number): AirportRecord[];
export function searchAirportsCatalog(query: string, options?: SearchAirportsOptions): AirportRecord[];
export function searchAirportsCatalog(
  query: string,
  optionsOrLimit: number | SearchAirportsOptions = 20
): AirportRecord[] {
  const limit = typeof optionsOrLimit === "number" ? optionsOrLimit : optionsOrLimit?.limit ?? 20;
  const countryFilter = typeof optionsOrLimit === "object" && optionsOrLimit?.country
    ? normalizeAirportSearchText(optionsOrLimit.country)
    : "";

  const q = normalizeAirportSearchText(query);
  if (!q && !countryFilter) {
    return GLOBAL_AIRPORTS_CATALOG.slice(0, limit);
  }

  const scored: { airport: AirportRecord; score: number }[] = [];

  for (const airport of GLOBAL_AIRPORTS_CATALOG) {
    let score = 0;
    const iata = airport.iata_code.toLowerCase();
    const icao = airport.icao_code.toLowerCase();
    const city = normalizeAirportSearchText(airport.city);
    const name = normalizeAirportSearchText(airport.name);
    const country = normalizeAirportSearchText(airport.country);
    const state = airport.state_province ? normalizeAirportSearchText(airport.state_province) : "";

    if (countryFilter && !country.includes(countryFilter) && airport.country_code.toLowerCase() !== countryFilter) {
      continue;
    }

    if (!q) {
      score = airport.country_code === "BR" ? 500 : 100;
    } else if (iata === q) {
      score = 1000;
    } else if (icao === q) {
      score = 950;
    } else if (iata.startsWith(q)) {
      score = 800;
    } else if (city === q) {
      score = 750;
    } else if (city.startsWith(q)) {
      score = 650;
    } else if (city.includes(q)) {
      score = 500;
    } else if (name.includes(q)) {
      score = 400;
    } else if (state === q || country.startsWith(q)) {
      score = 300;
    } else if (country.includes(q) || state.includes(q) || icao.includes(q)) {
      score = 200;
    }

    if (score > 0) {
      if (airport.country_code === "BR") {
        score += 10;
      }
      scored.push({ airport, score });
    }
  }

  scored.sort((a, b) => b.score - a.score || a.airport.city.localeCompare(b.airport.city));
  return scored.slice(0, limit).map((item) => item.airport);
}
